UPDATE kkdugi_user_base
SET user_nm      = #{name},
    user_dc      = #{remarks},
    user_img_src = #{image},
    user_email   = #{email},
    user_stat_cd = #{status},
    upd_dtm      = #{updatedAt},
    upd_id       = #{updaterId}
WHERE user_id = #{id}

